/// <summary>
/// PaffH 08.02.22
/// generate batch job for PA-Label creation
/// </summary>
class NDXBatchJobGeneratePALabel
    extends NDXBatchJobPALabel
{
}

Method.Source:
/// <summary>
/// PaffH 08.02.22
/// </summary>
/// <param name = "_batchJobId">RecId</param>
/// <returns>NDXBatchJobGeneratePALabel</returns>
static NDXBatchJobGeneratePALabel construct(RecId _batchJobId = 0)
{
    NDXBatchJobGeneratePALabel nDXBatchJobGeneratePALabel = new NDXBatchJobGeneratePALabel(_batchJobId);
    BatchHeader batchHeader = nDXBatchJobGeneratePALabel.parmBatchHeader();
    if (batchHeader.parmBatchGroup() != batchGroupId)
    {
        batchHeader.parmBatchGroup(nDXBatchJobGeneratePALabel.parmBatchGroup(batchGroupId, batchGroupIdDescription).Group);
    }
    return nDXBatchJobGeneratePALabel;
}

/// <summary>
/// PaffH 08.02.22
/// add task (ProdStatusChanged Generate TransportLabel) to Batch job
/// </summary>
/// <param name = "_args">Args</param>
/// <returns>RefRecId</returns>
// called from: NDXProdStatusChangedGenerateTransportLabelEventContractInteraction::triggerEvent()
public RefRecId addTask(Args _args = new Args())
{

    NDXProdStatusChangedGenerateTransportLabelController controller = NDXProdStatusChangedGenerateTransportLabelController::construct(_args);

    // Save ProdId to contranct
    if (_args && _args.parm())
    {
        NDXGenerateTransportLabelContract contract = controller.getDataContractObject('_contract');
        if (!contract)
        {
            // Function %1 was called with an invalid value
            throw Error(strFmt("@SYS23264", classStr(NDXGenerateTransportLabelContract)));
        }
        ProdId prodId = _args.parm();
        contract.prodId(prodId);
    }

    if (_args && _args.parm())
    {
        batchHeader.parmCaption(strFmt("@NDX:NDXShippingLabelForProductionOrder", _args.parm()));
    }
    controller.parmDialogCaption(batchHeader.parmCaption());
    batchHeader.addTask(controller);
    batchHeader.save();

    return batchHeader.parmBatchHeaderId();
}

/// <summary>
/// PaffH 11.05.22
/// </summary>
/// <returns>ClassDescription</returns>
client server static ClassDescription description()
{
    return "@NDX:NDXClassDescriptionNDXBatchJobGeneratePALabel";
}
